const eur=n=>EUR_F.format(Math.round(n*100)/100)+' €';
const uid=(()=>{let c=0;const A=new Uint8Array(6);return()=>{let x='';try{crypto.getRandomValues(A);x=[...A].map(b=>(b%36).toString(36)).join('')}catch(e){x=Math.random().toString(36).slice(2,8)}c=(c+1)%1296;return Date.now().toString(36)+c.toString(36).padStart(2,'0')+x}})();
const okId=v=>typeof v==='string'&&/^[\w.-]{1,64}$/.test(v);
