/* ---------- Couche de données (prête pour un backend) ----------
   Tout le code lit et écrit dans « db » puis appelle save().
   Aujourd'hui Store enregistre sur le téléphone ; plus tard il enverra à un serveur. */
const Store={
 key:'devisbtp',
 load(){try{return JSON.parse(localStorage.getItem(this.key))}catch(e){return null}},
 persist(d){const j=JSON.stringify(d),ts=Date.now();let ok=true;try{localStorage.setItem(this.key,j);localStorage.setItem('caso_ts',String(ts))}catch(e){ok=false}
  this.mirror(ok||(window.VAULT&&VAULT.on)?null:j,ts);return ok},
 _t:0,_j:null,_ts:0,
 mirror(j,ts){this._j=j;this._ts=ts;clearTimeout(this._t);this._t=setTimeout(()=>this.flush(),400)},
 flush(){if(!this._ts){try{this._ts=+(localStorage.getItem('caso_ts')||0)}catch(e){}}if(!this._ts)return;const ls={};try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(/^(caso_|devis)/.test(k)&&!/^caso_(test|essai_v|bk)/.test(k)&&!(window.VAULT&&VAULT.on&&VAULT.prot(k)))ls[k]=localStorage.getItem(k)}}catch(e){}
  if(this._j)ls[this.key]=this._j;if(window.VAULT)Object.assign(ls,VAULT.overflow);const v={ts:this._ts,ls};this._ts=0;this._j=null;(typeof CBK!=='undefined'?CBK.put(v):Promise.resolve()).catch(()=>{})}
};
window.addEventListener('pagehide',()=>Store.flush());document.addEventListener('visibilitychange',()=>{if(document.hidden)Store.flush()});
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{})}catch(e){}
let db=Store.load();
if(!db)db={prices:[
 {id:'def-mo',nom:"Main d'œuvre",unit:'h',prix:45,tva:20,four:''},
 {id:'def-dep',nom:'Déplacement',unit:'forfait',prix:30,tva:20,four:''},
 {id:'def-four',nom:'Petites fournitures',unit:'forfait',prix:20,tva:20,four:''}],
 quotes:[],counter:0,prof:{},hist:[]};
if(!db.hist)db.hist=[];
if(!db.sup)db.sup={};
if(!db.chantiers)db.chantiers=[];if(!db.people)db.people=[];if(!db.pts)db.pts=[];
if(!db.clients)db.clients=[];if(!db.suppliers)db.suppliers=[];
if(!db.projects)db.projects=[];if(!db.plans)db.plans=[];if(!db.events)db.events=[];if(!db.cvTpl)db.cvTpl=[];if(!db.invoices)db.invoices=[];
/* Suivi des changements, pour synchroniser plus tard : chaque enregistrement reçoit un id
   et une date de dernière modification ; chaque suppression laisse une trace dans db.tomb. */
const COLL=['prices','quotes','hist','chantiers','people','pts','clients','suppliers','projects','plans','events','invoices','memo','rapports'];
let snap={};
function fp(o){const u=o.updatedAt;if(u===undefined)return JSON.stringify(o);o.updatedAt=undefined;const s=JSON.stringify(o);o.updatedAt=u;return s}
function initSnap(){
 snap={};
 COLL.forEach(c=>{const cur={};(db[c]||[]).forEach(r=>{if(r.id)cur[r.id]=fp(r)});snap[c]=cur})}
function stamp(){
 const now=Date.now();
 db.schema=2;
 if(!db.device)db.device='d'+uid();
 if(!db.tomb)db.tomb=[];
 if(db.tomb.length&&now-db.tomb[0].at>90*864e5)db.tomb=db.tomb.filter(t=>now-t.at<90*864e5);if(db.tomb.length>2000)db.tomb=db.tomb.slice(-2000);
 COLL.forEach(c=>{
  const list=Array.isArray(db[c])?db[c]:[],cur={};
  list.forEach(r=>{
   if(!r.id)r.id=uid();
   const f=fp(r);cur[r.id]=f;
   if(!r.updatedAt||(snap[c]&&snap[c][r.id]!==f))r.updatedAt=now});
  Object.keys(snap[c]||{}).forEach(id=>{if(!(id in cur))db.tomb.push({c,id,at:now})});
  snap[c]=cur});
}
let saveWarnAt=0;function save(){stamp();if(!Store.persist(db)&&Date.now()-saveWarnAt>60000){saveWarnAt=Date.now();alert('La mémoire de casô sur ce téléphone est pleine : les dernières modifications ne sont pas enregistrées.\n\nFais une sauvegarde (Compte › Sauvegarder), puis supprime des photos ou de vieux devis.')}syncSoon()}
if(window.VAULT)VAULT.onFail=()=>{if(Date.now()-saveWarnAt>60000){saveWarnAt=Date.now();alert('La mémoire de casô sur ce téléphone est pleine : les dernières modifications ne sont pas enregistrées.\n\nFais une sauvegarde (Compte › Sauvegarder), puis supprime des photos ou de vieux devis.')}};
initSnap();

