/* ---------- Langue de l'appli (le devis, le PDF et le message restent en français) ---------- */
/* traductions de l'interface : i18n/ui-xx.json, seulement la langue choisie ; gardée sur l'appareil, mise à jour en arrière-plan */
const I18N_DATA={},I18N_SRC={},I18N_LANGS=["pt", "es", "it", "ro", "tr", "pl", "en", "ar", "ru"];
for(const l of I18N_LANGS){try{const v=localStorage.getItem('caso_ui_'+l);if(v)I18N_SRC[l]=v}catch(e){}}
const I18N_ATT={};function i18nCharger(l){if(!I18N_LANGS.includes(l))return Promise.resolve(false);if(I18N_ATT[l])return I18N_ATT[l];
 return I18N_ATT[l]=fetch('i18n/ui-'+l+'.json').then(r=>{if(!r.ok)throw new Error('ui '+r.status);return r.text()}).then(t=>{JSON.parse(t);const neuf=t!==I18N_SRC[l];
  if(neuf){I18N_SRC[l]=t;try{localStorage.setItem('caso_ui_'+l,t)}catch(e){}if(!i18nLazy(l))i18nDef(l);I18N.rx={}}I18N_ATT[l]=Promise.resolve(false);return neuf}).catch(()=>{I18N_ATT[l]=null;return false})};
function i18nFix(l,v){if(l!=='fr'&&VL_DEF[l]){for(let i=0;i<=10;i++){const k=VL_DEF.fr.ui[i];if(!(k in v))v[k]=VL_DEF[l].ui[i]}}const o=i18nOver()[l];if(o)Object.assign(v,o);return v}
function i18nSetLang(l,v){Object.defineProperty(I18N_DATA,l,{value:v,enumerable:true,writable:true,configurable:true});return v}
function i18nDef(l){Object.defineProperty(I18N_DATA,l,{enumerable:true,configurable:true,get(){if(I18N_SRC[l]==null)return undefined;return i18nSetLang(l,i18nFix(l,JSON.parse(I18N_SRC[l])))},set(v){i18nSetLang(l,v)}})}
for(const l of I18N_LANGS)i18nDef(l);
const i18nLazy=l=>{const d=Object.getOwnPropertyDescriptor(I18N_DATA,l);return !!(d&&d.get)};
const I18N={lang:'fr',rx:{},tx:new WeakMap(),at:new WeakMap(),obs:null,miss:new Set()};
const I18N_FRW=/(^|[\s'’])(le|la|les|de|des|du|un|une|ton|ta|tes|est|pour|avec|dans|sur|et|à|au|aux|ce|cette|pas|plus|ou|par|en)(?=[\s.,:;!?…»]|$)|[éèêàùçœ]/i;
function i18nOver(){try{return JSON.parse(localStorage.getItem('caso_i18n_over')||'{}')}catch(e){return{}}}
function i18nMerge(){
 for(const l in VL_DEF){if(l==='fr'||i18nLazy(l))continue;I18N_DATA[l]=I18N_DATA[l]||{};for(let i=0;i<=10;i++){const k=VL_DEF.fr.ui[i];if(!(k in I18N_DATA[l]))I18N_DATA[l][k]=VL_DEF[l].ui[i]}}
 const o=i18nOver();for(const l in o){if(i18nLazy(l))continue;I18N_DATA[l]=I18N_DATA[l]||{};Object.assign(I18N_DATA[l],o[l])}I18N.rx={}}
const I18N_ATTR=['placeholder','aria-label','title'];
function i18nPrep(l){
 if(I18N.rx[l])return I18N.rx[l];
 const d=I18N_DATA[l]||{},ex=new Map(),pats=[];
 for(const k in d){
  if(/\{\d\}/.test(k)){
   const order=[...k.matchAll(/\{(\d)\}/g)].map(m=>+m[1]);
   const src=k.split(/\{\d\}/).map(x=>x.replace(/[.*+?^$()|[\]\\{}]/g,'\\$&')).join('(.+?)');
   pats.push({re:new RegExp('^'+src+'$'),order,v:d[k],n:k.length});
  }else ex.set(k,d[k]);
 }
 pats.sort((a,b)=>b.n-a.n);
 return I18N.rx[l]={ex,pats};
}
/** Traduit une phrase française de l'interface. Ce qui n'est pas connu reste tel quel. */
function i18nT(s,l){
 l=l||I18N.lang;s=String(s??'');
 if(l==='fr'||!/\p{L}{2}/u.test(s))return s;
 const R=i18nPrep(l);const C=R.cache||(R.cache=new Map()),hit=C.get(s);if(hit!==undefined)return hit;
 const k=s.replace(/\s+/g,' ').trim();
 let v=R.ex.get(k);
 if(v==null)for(const p of R.pats){const m=k.match(p.re);if(m){
  v=p.v.replace(/\{(\d)\}/g,(x,n)=>{const i=p.order.indexOf(+n);if(i<0)return x;const c=m[i+1];return R.ex.get(c)??c});break}}
 if(v==null){if(k.length>3&&k.length<300&&I18N_FRW.test(k)&&!/^[\d\s.,:€%/-]+$/.test(k))I18N.miss.add(k);if(C.size<5000)C.set(s,s);return s}
 const out=s.match(/^\s*/)[0]+v+s.match(/\s*$/)[0];if(C.size<5000)C.set(s,out);return out;
}
function i18nSkip(el){return !el||!!el.closest('script,style,textarea,[data-noi18n]')}
function i18nText(n,ok){
 const p=n.parentElement;if(!ok&&(!n.isConnected||i18nSkip(p)))return;
 const cur=n.data;let o=I18N.tx.get(n);
 if(!o||cur!==o.out)o={fr:cur,out:cur};
 if(p.tagName==='OPTION'&&!p.hasAttribute('value'))p.setAttribute('value',o.fr.trim());
 o.out=i18nT(o.fr);I18N.tx.set(n,o);
 if(cur!==o.out)n.data=o.out;
}
function i18nAttr(el,a,ok){
 if(!ok&&(!el||!el.isConnected||i18nSkip(el)))return;const cur=el.getAttribute(a);if(cur==null)return;
 let m=I18N.at.get(el);if(!m){m={};I18N.at.set(el,m)}
 let o=m[a];if(!o||cur!==o.out)o=m[a]={fr:cur,out:cur};
 o.out=i18nT(o.fr);if(cur!==o.out)el.setAttribute(a,o.out);
}
const I18N_SVG=/^(path|circle|rect|line|polyline|polygon|ellipse|use|defs|symbol|clipPath|mask|pattern|linearGradient|radialGradient|stop)$/;
const I18N_FILTER={acceptNode(n){if(n.nodeType!==1)return 1;
 if(n.namespaceURI==='http://www.w3.org/2000/svg'?I18N_SVG.test(n.localName):(n.tagName==='SCRIPT'||n.tagName==='STYLE'||n.tagName==='TEXTAREA'||n.hasAttribute('data-noi18n')))return 2;return 1}};
function i18nWalk(root){
 if(!root||!root.isConnected)return;
 if(root.nodeType===3){i18nText(root);return}
 if(root.nodeType!==1)return;
 if(i18nSkip(root))return;
 I18N_ATTR.forEach(a=>root.hasAttribute(a)&&i18nAttr(root,a));
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT,I18N_FILTER);let n;
 while((n=w.nextNode())){
  if(n.nodeType===3)i18nText(n,1);
  else I18N_ATTR.forEach(a=>n.hasAttribute(a)&&i18nAttr(n,a,1))
 }
}
function i18nApply(l){
 /* langue pas encore sur l'appareil, ou peut-être mise à jour : on la charge, puis on l'applique */
 if(l&&l!=='fr'&&I18N_LANGS.includes(l)){const had=I18N_SRC[l]!=null;i18nCharger(l).then(neuf=>{if(neuf&&I18N.voulu===l)i18nApply(l)});if(!had)I18N.voulu=l}
 I18N.voulu=l;
 I18N.lang=I18N_DATA[l]||l==='fr'?l:'fr';
 const d=VL_DEF[I18N.lang];
 document.documentElement.lang=I18N.lang;
 document.documentElement.dir=d&&d.rtl?'rtl':'ltr';
 if(I18N.lang==='fr'&&!I18N.used)return;
 I18N.used=1;i18nWalk(document.body);
}
function i18nStart(l){
 i18nMerge();
 // boîtes de dialogue
 if(!window.__i18nDlg){window.__i18nDlg=1;
  const A=window.alert,C=window.confirm,P=window.prompt;
  window.alert=m=>A.call(window,i18nT(m));
  window.confirm=m=>C.call(window,i18nT(m));
  window.prompt=(m,d)=>P.call(window,i18nT(m),d);
 }
 const pr=document.getElementById('print');if(pr){pr.setAttribute('data-noi18n','');pr.setAttribute('dir','ltr');pr.lang='fr'}
 i18nApply(l);
 if(!I18N.obs&&window.MutationObserver){
  I18N.obs=new MutationObserver(ms=>{
   if(I18N.lang==='fr')return;
   for(const m of ms){
    if(m.type==='characterData')i18nText(m.target);
    else if(m.type==='attributes')i18nAttr(m.target,m.attributeName);
    else m.addedNodes.forEach(i18nWalk);
   }
  });
  I18N.obs.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:I18N_ATTR});
 }
}
/* Éditeur de traduction (pour les usagers qui parlent la langue) */
function trSaveOne(k,v){
 const l=I18N.lang,o=i18nOver();o[l]=o[l]||{};
 if(v.trim())o[l][k]=v.trim();else delete o[l][k];
 try{localStorage.setItem('caso_i18n_over',JSON.stringify(o))}catch(e){}
 I18N_DATA[l]=I18N_DATA[l]||{};if(v.trim())I18N_DATA[l][k]=v.trim();I18N.rx={};I18N.miss.delete(k);
 i18nApply(l);
}
function trRender(){
 const l=I18N.lang,d=I18N_DATA[l]||{},ov=(i18nOver()[l])||{},q=vnNorm($('trQ').value||'');
 const row=(k,v,mine)=>`<div class="tr-row${mine?' mine':''}"><div class="tr-fr" lang="fr" dir="ltr" data-noi18n>${esc(k)}</div><textarea rows="${Math.min(5,Math.ceil(((v||k).length+1)/30))}" data-noi18n dir="auto" data-k="${esc(k)}" onchange="trSaveOne(this.dataset.k,this.value)">${esc(v||'')}</textarea></div>`;
 const dj=JSON.stringify(db);const miss=[...I18N.miss].filter(k=>!d[k]&&!dj.includes(JSON.stringify(k).slice(1,-1))&&(!q||vnNorm(k).includes(q)));
 $('trMissBox').innerHTML=miss.length?`<h3 class="tr-h">Phrases pas encore traduites (${miss.length})</h3>`+miss.map(k=>row(k,'',0)).join(''):'';
 const ks=Object.keys(d).filter(k=>!q||vnNorm(k).includes(q)||vnNorm(d[k]).includes(q)).sort((a,b)=>(ov[b]?1:0)-(ov[a]?1:0));
 $('trList').innerHTML=`<h3 class="tr-h">Toutes les phrases (${ks.length})</h3>`+ks.slice(0,q?400:150).map(k=>row(k,d[k],!!ov[k])).join('')+(!q&&ks.length>150?'<p class="mut">Cherche un mot pour voir les autres phrases.</p>':'');
}
function trShare(){
 const l=I18N.lang,o=(i18nOver()[l])||{};const n=Object.keys(o).length;
 if(!n){alert('Aucune correction pour le moment.');return}
 const txt='casô-traduction '+JSON.stringify({lang:l,v:1,t:o});
 if(navigator.share)navigator.share({title:'casô',text:txt}).catch(()=>{});
 else if(navigator.clipboard)navigator.clipboard.writeText(txt).then(()=>alert('Corrections copiées. Colle-les dans un message.'),()=>prompt('Copie ce texte :',txt));
 else prompt('Copie ce texte :',txt);
}
function trImport(){
 const raw=prompt('Colle ici les corrections reçues :');if(!raw)return;
 try{const j=JSON.parse(raw.slice(raw.indexOf('{')));if(!j.lang||!j.t||!VL_DEF[j.lang])throw 0;
  const o=i18nOver();o[j.lang]=Object.assign(o[j.lang]||{},j.t);localStorage.setItem('caso_i18n_over',JSON.stringify(o));
  i18nMerge();i18nApply(I18N.lang);trRender();alert(Object.keys(j.t).length+' corrections ajoutées.');
 }catch(e){alert('Texte non reconnu.')}
}
function trReset(){
 if(!confirm('Effacer toutes tes corrections de traduction ?'))return;
 const o=i18nOver();delete o[I18N.lang];try{localStorage.setItem('caso_i18n_over',JSON.stringify(o))}catch(e){}
 location.reload();
}
/* Noms en français pour le devis */
function frOf(txt){ // traduit un libellé tapé dans la langue de l'usager ; ok=false s'il reste des mots inconnus
 const l=I18N.lang;if(l==='fr'||!txt)return{t:txt,ok:true};
 const r=vlTranslate(txt,l);const t=r.t.replace(/\s+/g,' ').trim();
 return{t:t?t[0].toUpperCase()+t.slice(1):t,ok:!r.miss.length};
}
function pDisp(p){return p.loc&&p.loc.l===I18N.lang?p.loc.t:p.nom}

