function vlBuild(){
 for(const k in VL_DEF){if(Object.getOwnPropertyDescriptor(VL,k))continue;
  Object.defineProperty(VL,k,{enumerable:true,configurable:true,get(){const v=vlBuildOne(k);Object.defineProperty(VL,k,{value:v,enumerable:true,writable:true,configurable:true});return v}})}
}
function vlBuildOne(k){
 {const d=VL_DEF[k],m=new Map();let max=1;
  ((VL_EXTRA[k]||'')+'|'+(VL_MORE[k]||'')+'|'+(d.w||'')+'|'+(VL_DIM[k]||'')).split(/\|\s*/).forEach(p=>{const i=p.indexOf('=');if(i<1)return;const a=vnNorm(p.slice(0,i)),b=p.slice(i+1).trim();if(!a)return;m.set(a,b);max=Math.max(max,a.split(' ').length)});
  return{...d,map:m,max,stopSet:new Set(vnNorm(d.stop).split(' ').filter(Boolean))};
 }
}
/* Dictionnaire appris : les corrections de l'usager (mot dans sa langue -> français) */
function ulexAll(){try{return JSON.parse(localStorage.getItem('caso_lex')||'{}')}catch(e){return{}}}
function ulexGet(l){const o=ulexAll()[l]||{},m=new Map();let max=1;for(const k in o){m.set(k,o[k]);max=Math.max(max,k.split(' ').length)}return{m,max}}
function ulexLearn(l,local,fr){
 local=vnNorm(local);fr=String(fr||'').trim();if(!l||l==='fr'||!local||!fr||local===vnNorm(fr)||local.split(' ').length>6)return;
 const a=ulexAll();a[l]=a[l]||{};if(a[l][local]===fr)return;a[l][local]=fr;
 try{localStorage.setItem('caso_lex',JSON.stringify(a))}catch(e){}
}
function vlGuess(){
 const ls=[].concat(navigator.languages||[],navigator.language||[]);
 for(const l of ls){const c=String(l).slice(0,2).toLowerCase();if(VL_DEF[c])return c}
 return 'fr';
}
function vlGet(){let l=null;try{l=localStorage.getItem('caso_lang')}catch(e){}return VL_DEF[l]?l:vlGuess()}
function vlSet(l){try{localStorage.setItem('caso_lang',l)}catch(e){}}
function vlRec(l){const d=VL_DEF[l]||VL_DEF.fr;if(l==='pt'&&/^pt-br/i.test(navigator.language||''))return'pt-BR';return d.rec}
function vlT(i,l){const d=VL_DEF[l||VN.lang]||VL_DEF.fr;return d.ui[i]||VL_DEF.fr.ui[i]}
/** Devine la langue d'un texte. Renvoie {l,score} ou null si pas sûr. */
const VL_FR_PETITS=new Set(['a','de','la','le','les','des','du','en','et','un','une','au','aux','pour','sur','avec','par','ou']);
function vlDetect(txt){
 const s=String(txt||'');const ar=(s.match(/[؀-ۿ]/g)||[]).length,lat=(s.match(/[A-Za-zÀ-ž]/g)||[]).length;
 if(ar>lat)return{l:'ar',score:9};
 const cy=(s.match(/[\u0400-\u04FF]/g)||[]).length;if(cy>lat)return{l:'ru',score:9};
 const ws=vnNorm(s).replace(/[^a-z0-9ăâîșțşçğıöüł' ]/g,' ').split(' ').filter(Boolean);
 if(!VL.fr)vlBuild();
 const sc={};
 for(const k in VL){if(k==='ar')continue;let n=0;
  let st=0;for(let i=0;i<ws.length;i++){/* « a », « de », « la »… sont aussi des petits mots français : ils ne font pas pencher vers une autre langue */if(VL[k].stopSet.has(ws[i])&&(k==='fr'||!VL.fr.stopSet.has(ws[i])&&!VL_FR_PETITS.has(ws[i]))){n+=1;st++}
   if(k!=='fr'){const w2=i+1<ws.length?ws[i]+' '+ws[i+1]:null,v=VL[k].map.has(ws[i])?VL[k].map.get(ws[i]):(w2&&VL[k].map.has(w2)?VL[k].map.get(w2):null);
    if(v&&vnNorm(v)!==ws[i]&&!(VL.fr.stopSet.has(ws[i])))n+=.5}}
  sc[k]=k==='fr'||st>=2?n:0}
 const best=Object.keys(sc).sort((a,b)=>sc[b]-sc[a]);
 if(!best.length||sc[best[0]]<2||sc[best[0]]<sc[best[1]]*1.4)return null;
 return{l:best[0],score:sc[best[0]]};
}
/** Traduit mot à mot (expressions d'abord) vers un français que le lecteur de notes comprend. */
function vlTranslate(txt,l){
 if(!VL.fr)vlBuild();
 const L=VL[l];if(!L||l==='fr')return{t:String(txt),miss:[]};
 const miss=[],segs=[],U=ulexGet(l);
 const src=String(txt).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/،/g,',').replace(/؛/g,';').replace(/؟/g,'?').replace(/кв\.\s*м\.?/gi,'м2').replace(/м²/g,'м2').replace(/пог\.\s*м\.?/gi,'пог м');
 const out=src.split(/([.,;!?\n]+)/).map(seg=>{
  if(/^[.,;!?\n]+$/.test(seg))return seg+' ';
  const W=seg.split(/\s+/).filter(Boolean),N=W.map(vnNorm);const o=[];
  let nameLeft=0;
  for(let i=0;i<W.length;){
   let hit=0;
   if(nameLeft>0){const civ=U.m.get(N[i])||L.map.get(N[i]);if(civ&&/^(monsieur|madame|mme)$/.test(vnNorm(civ))){o.push(civ);i++;continue}
    const cap=/^\p{Lu}/u.test(W[i]);if(cap||nameLeft===2){o.push(W[i]);i++;nameLeft=cap?nameLeft-1:0;continue}nameLeft=0}
   for(let n=Math.min(Math.max(L.max,U.max),W.length-i);n>=1;n--){const k=N.slice(i,i+n).join(' ');
    if(U.m.has(k)){o.push(U.m.get(k));i+=n;hit=1;break}
    if(L.map.has(k)){const v=L.map.get(k);if(v)o.push(v);i+=n;hit=1;if(/^(client|monsieur|madame|chez)$/.test(vnNorm(v)))nameLeft=2;break}}
   if(hit)continue;
   let w=W[i],nw=N[i];
   if(l==='ar'){// préfixes و / ال / بال / لل / ب / ل
    for(const p of ['وال','بال','لل','ال','و','ب','ل','ف']){if(nw.startsWith(p)&&nw.length-p.length>=2){const r=nw.slice(p.length);
     if(L.map.has(r)){const v=L.map.get(r);o.push((p[0]==='و'?'et ':'')+v);hit=1;break}
     if(L.map.has('ال'+r)){o.push((p[0]==='و'?'et ':'')+L.map.get('ال'+r));hit=1;break}}}
    if(hit){i++;continue}
   }
   if(/[\p{L}]{3,}/u.test(w)&&!/^\d/.test(w))miss.push(w);
   o.push(w);i++;
  }
  const tj=o.join(' ');if(seg.trim())segs.push({o:seg.trim(),t:vnNorm(tj)});return tj;
 }).map(x=>l==='tr'?vlTrOrder(x):x).join('').replace(/\s+([.,;!?])/g,'$1').replace(/\b(pas d|d)e (?=[aeiouyhéèêàâîôû])/gi,"$1'").replace(/\s+/g,' ').trim();
 return{t:out,miss,segs};
}
// turc : le verbe est à la fin (« çimento almak lazım » -> « il faut acheter ciment »)
function vlTrOrder(seg){
 let m=seg.trim().match(/^(.*?)\s*\b(acheter|commander|appeler|envoyer|faire)?\s*il faut$/);
 if(m&&(m[1]||m[2]))return ' il faut '+(m[2]?m[2]+' ':'')+m[1]+' ';
 m=seg.trim().match(/^(.+?)\s+(acheter|commander|appeler|envoyer)$/);
 if(m)return ' '+m[2]+' '+m[1]+' ';
 return seg;
}
